import 'dart:convert';
import 'dart:io';

import 'package:http/http.dart' as http;
import 'package:http/io_client.dart';

class ApiException implements Exception {
  final String message;
  final int? statusCode;

  ApiException(this.message, [this.statusCode]);

  @override
  String toString() => message;
}

class ApiService {
  final String baseUrl;
  final String? token;
  late final http.Client _client;

  ApiService({required String baseUrl, this.token})
      : baseUrl = _normaliseBaseUrl(baseUrl) {
    // This accepts the local development certificate generated by the project.
    // Replace with a publicly trusted certificate before production deployment.
    final io = HttpClient()
      ..badCertificateCallback =
          (X509Certificate cert, String host, int port) => true;
    _client = IOClient(io);
  }

  static String _normaliseBaseUrl(String input) {
    var value = input.trim();
    if (value.isEmpty) {
      throw ApiException('Enter the server address shown by run.sh.');
    }
    if (!value.startsWith('http://') && !value.startsWith('https://')) {
      value = 'https://$value';
    }
    while (value.endsWith('/')) {
      value = value.substring(0, value.length - 1);
    }
    return value;
  }

  Map<String, String> get _headers => {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        if (token != null && token!.isNotEmpty) 'Authorization': 'Bearer $token',
      };

  Future<Map<String, dynamic>> login(String identifier, String password) async {
    return _decode(await _client.post(
      Uri.parse('$baseUrl/api/student/login'),
      headers: _headers,
      body: jsonEncode({'identifier': identifier, 'password': password}),
    ));
  }

  Future<Map<String, dynamic>> dashboard() async {
    return _decode(await _client.get(
      Uri.parse('$baseUrl/api/student/dashboard'),
      headers: _headers,
    ));
  }

  Future<Map<String, dynamic>> profile() async {
    return _decode(await _client.get(
      Uri.parse('$baseUrl/api/student/profile'),
      headers: _headers,
    ));
  }

  Future<Map<String, dynamic>> courses() async {
    return _decode(await _client.get(
      Uri.parse('$baseUrl/api/student/courses'),
      headers: _headers,
    ));
  }

  Future<Map<String, dynamic>> attendance({int limit = 100}) async {
    return _decode(await _client.get(
      Uri.parse('$baseUrl/api/student/attendance?limit=$limit'),
      headers: _headers,
    ));
  }

  Future<Map<String, dynamic>> checkIn(String attendanceToken) async {
    return _decode(await _client.post(
      Uri.parse('$baseUrl/api/student/checkin'),
      headers: _headers,
      body: jsonEncode({'token': attendanceToken}),
    ));
  }

  Future<void> logout() async {
    try {
      await _client.post(
        Uri.parse('$baseUrl/api/student/logout'),
        headers: _headers,
      );
    } catch (_) {
      // Local logout still succeeds even when the server is unavailable.
    }
  }

  Map<String, dynamic> _decode(http.Response response) {
    dynamic body;
    try {
      body = response.body.isEmpty ? <String, dynamic>{} : jsonDecode(response.body);
    } catch (_) {
      throw ApiException(
        'The server returned an unexpected response (${response.statusCode}).',
        response.statusCode,
      );
    }

    if (response.statusCode < 200 || response.statusCode >= 300) {
      var message = 'Request failed (${response.statusCode}).';
      if (body is Map<String, dynamic>) {
        final detail = body['detail'] ?? body['message'];
        if (detail != null) message = detail.toString();
      }
      throw ApiException(message, response.statusCode);
    }

    if (body is! Map<String, dynamic>) {
      throw ApiException('Invalid response from the attendance server.');
    }
    return body;
  }

  void close() => _client.close();
}
